#!/usr/bin/env bash
# Same-conditions comparison: every gateway proxies GET /echo to the same nginx upstream, load is
# generated by wrk inside the same Docker network. Usage: tests/bench/compare.sh [duration] [runs]
set -euo pipefail
cd "$(dirname "$0")"
D=${1:-15}; RUNS=${2:-2}; T=${WRK_THREADS:-2}; C=${WRK_CONNS:-100}
NET=sancus-bench
docker network inspect $NET >/dev/null 2>&1 || docker network create $NET >/dev/null
docker build -q -t sancus-wrk -f Dockerfile.wrk . >/dev/null
cleanup() { docker rm -f bench-upstream bench-redis bench-gw >/dev/null 2>&1 || true; }
trap cleanup EXIT; cleanup
docker run -d --rm --name bench-upstream --network $NET --network-alias upstream -v "$PWD/nginx-upstream.conf:/etc/nginx/nginx.conf:ro" nginx:1.27-alpine >/dev/null
docker run -d --rm --name bench-redis --network $NET redis:7-alpine >/dev/null
sleep 2

wrkrun() { docker run --rm --network $NET sancus-wrk -t$T -c$C -d${D}s --latency "$1"; }
measure() { # name url
  local name=$1 url=$2 out rps p50 p99 err
  local ready=0
  for i in $(seq 1 30); do docker run --rm --network $NET curlimages/curl:8.10.1 -s -o /dev/null -w '%{http_code}' "$url" 2>/dev/null | grep -q 200 && ready=1 && break; sleep 1; done
  [ $ready = 1 ] || { echo "$name: never returned 200 at $url"; docker logs bench-gw 2>&1 | tail -5; return 1; }
  wrkrun "$url" >/dev/null   # warmup
  local best=""
  for i in $(seq 1 $RUNS); do
    out=$(wrkrun "$url")
    rps=$(echo "$out" | awk '/Requests\/sec/{print $2}'); p50=$(echo "$out" | awk '/ 50%/{print $2}'); p99=$(echo "$out" | awk '/ 99%/{print $2}'); err=$(echo "$out" | awk '/Non-2xx/{print $NF}')
    printf '%-10s run %d: %8s req/s  p50 %-8s p99 %-8s %s\n' "$name" "$i" "$rps" "$p50" "$p99" "${err:+NON-2XX=$err}"
  done
  docker stats --no-stream --format '{{.Name}} cpu={{.CPUPerc}} mem={{.MemUsage}}' bench-gw 2>/dev/null | sed 's/^/           /' || true
}

echo "== direct upstream =="; measure nginx http://bench-upstream/echo
GW=(
  "sancus|3000|/api/bench/echo|-e IP_RATE_LIMIT_ENABLED=false -e LOG_LEVEL=warn -e CONFIG_WATCH=false -e REDIS_URL=redis://bench-redis:6379 -e WORKERS=2 -v $PWD/sancus-bench.yml:/app/api_configs/bench.yml:ro ${SANCUS_IMAGE:-sancus:slim}"
  "traefik|80|/echo|-v $PWD/traefik-dynamic.yml:/etc/traefik/dynamic.yml:ro traefik:v3.1 --providers.file.filename=/etc/traefik/dynamic.yml --entrypoints.web.address=:80 --log.level=ERROR"
  "kong|8000|/echo|-e KONG_DATABASE=off -e KONG_DECLARATIVE_CONFIG=/kong/kong.yml -e KONG_PROXY_ACCESS_LOG=off -e KONG_NGINX_WORKER_PROCESSES=2 -e KONG_LOG_LEVEL=error -v $PWD/kong.yml:/kong/kong.yml:ro kong:3.7"
  "apisix|9080|/echo|-v $PWD/apisix-config.yaml:/usr/local/apisix/conf/config.yaml:ro -v $PWD/apisix.yaml:/usr/local/apisix/conf/apisix.yaml:ro apache/apisix:3.9.1-debian"
  "krakend|8080|/echo|-v $PWD/krakend.json:/etc/krakend/krakend.json:ro devopsfaith/krakend:2.7"
)
for spec in "${GW[@]}"; do
  IFS='|' read -r name port path args <<<"$spec"
  echo "== $name =="
  docker run -d --rm --name bench-gw --network $NET $args >/dev/null
  measure "$name" "http://bench-gw:$port$path" || echo "$name FAILED"
  docker rm -f bench-gw >/dev/null 2>&1 || true
done
